import type { SheetItem, SpellSchool, WarbandDef } from '../types';
import equipment from './equipment.json';
import { ALL_WARBANDS } from './warbands';
import { ALL_SPELL_SCHOOLS } from './spells';
import { ALL_WARBAND_ITEM_FILES } from './warband-equipment';

// Data lives in ./warbands and ./spells (schemas: WARBAND_SCHEMA.md, SPELL_SCHEMA.md); indexes are generated by scripts/gen-index.mjs.
export const WARBANDS: WarbandDef[] = [...ALL_WARBANDS].sort((a, b) => a.name.localeCompare(b.name));
export const SHEET: SheetItem[] = (equipment as SheetItem[]).map((s) => ({ ...s, source: 'sheet' as const }));
/** Warband-only weapons and armour with draft d12 stats (WARBAND_EQUIPMENT_SCHEMA.md). */
export const WARBAND_ITEMS: SheetItem[] = ALL_WARBAND_ITEM_FILES.flat().map((s) => ({ ...s, raw: s.raw ?? 'Same', cls: s.cls ?? null, source: 'warband' as const }));
export const SPELL_SCHOOLS: SpellSchool[] = [...ALL_SPELL_SCHOOLS].sort((a, b) => a.name.localeCompare(b.name));

export function getWarband(id: string): WarbandDef | undefined {
  return WARBANDS.find((w) => w.id === id);
}

/** The spell school a fighter's `spellcaster` string refers to. */
export function schoolFor(spellcaster: string | null | undefined): SpellSchool | undefined {
  if (!spellcaster) return undefined;
  const k = spellcaster.toLowerCase();
  return SPELL_SCHOOLS.find((s) => s.aliases.some((a) => a.toLowerCase() === k) || s.name.toLowerCase() === k);
}
